useEffect does not run twice in strict mode and dev run due to the remount semantic.

React version: 19.1.1

```tsx
function DebugMount() {
  useEffect(() => {
    console.log('[DebugMount] mounted');
    return () => console.log('[DebugMount] cleanup');
  }, []);
  return null;
}


function App() {
   return <DebugMount/>;
}

createRoot(document.getElementById('root')!).render(
