      console.log("effect run", i);
      i = i + 1;
      return _temp;
    }
    function _temp() {
      console.log("cleanup run", i);
    }
    ```

    As you can see in the bottom at `_temp2` and `_temp`, the compiler has optimized away the copy (`runNumber`) and produces an incorrect result.

If changing to use `i++` instead of `i += 1` i.e. an `UpdateExpression`, React Compiler correctly bails out ([playground](https://playground.react.dev/#N4Igzg9grgTgxgUxALhAGwQFwAQEtsC82ADANwA6AdlQgB4AOEMOAZlJXJrhJdgIL16ACgCU2YFWzYoYBAFEWLBJyGjCAPnGSp2ODzA4Y7AHJQAtgCMEMQnm1S9lSBgB0aCAHMhAcgSLlhuzeADTYRpSmltYi9ngA1HEUvDowWLC8agSaEsk6uvoQru5e3nAYAIaUUPRhQaHhkVYwMbnYAL7abaEA2gC6LVKpmOnYADwAJrgAbuoA8gDSowD0kzNUHZQgwSCOLLgeKCC4ZozM2JgAnvQI4tgACmhQHriUs-Rc+u3YLDAQZtjeCzlKxoAC09Eez0ooNS5U4oL0J1wGBgK1wBm8SSoQhyUiWS0R9GR5Q+lAAshBxghkNhyCBymg0HT1tgwCT0XsEGB7pCXm9SWARKQtuAABYQADuAElKJhrJQGWAUCxFQg2kA)):

